'use strict';
const $ = id => document.getElementById(id);
const esc = text => String(text ?? '').replace(/[&<>"']/g, ch => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const states = {pending:'排队中',running:'研究中',completed:'研究完成',failed:'研究失败',interrupted:'研究中断'};
const kinds = {plan:'规划问题',search:'检索资料',read:'阅读摘要',extract:'提取结论',judge:'判断补检',report:'综合报告',complete:'完成',error:'错误'};
let activeId = null, timer = null, current = null, creating = false;
async function api(url, options) {const r=await fetch(url, options);const v=await r.json();if(!r.ok)throw Error(v.error||'请求失败');return v;}
function showError(error) {$('error').textContent=error.message;$('error').hidden=false;}
function modeChanged(){const demo=$('mode').value==='demo';$('topic').readOnly=demo;if(demo)$('topic').value='RAG 与微调如何选择';$('mode-note').textContent=demo?'固定教学样例 · 无需密钥 · 不代表实时搜索结果':'使用你在 .env 中配置的搜索与模型 API · 将发送研究主题和资料摘要';}
$('mode').addEventListener('change',modeChanged);modeChanged();
async function history(){try{const list=await api('/api/research');$('history').innerHTML=list.length?list.map(x=>`<button class="history-item" data-id="${esc(x.id)}">${esc(x.topic)}<small>${esc(states[x.status]||x.status)} · ${x.mode==='demo'?'演示':'联网'} · ${esc(x.created_at.slice(0,10))}</small></button>`).join(''):'<p class="hint">还没有研究记录</p>';}catch(e){showError(e);}}
$('refresh').onclick=history;
$('history').onclick=e=>{const b=e.target.closest('[data-id]');if(b)select(b.dataset.id);};
function claim(c){return `<div class="claim">${esc(c.text)} ${c.source_ids.length?c.source_ids.map(i=>`<a href="#source-${i}" class="cite" data-source="${i}">[${i}]</a>`).join(''):'<span class="inference">模型推断</span>'}</div>`;}
function render(record){current=record;$('empty').hidden=true;$('workspace').hidden=false;$('status').textContent=(states[record.status]||record.status)+(record.mode==='demo'?' · 离线演示':' · 实时联网');$('result-title').textContent=record.topic;$('source-count').textContent=record.sources.length;$('metrics').innerHTML=`<span><b>${record.iterations}</b>研究轮次</span><span><b>${record.sources.length}</b>资料来源</span><span><b>${record.queries.length}</b>检索关键词</span><span><b>${record.process.length}</b>过程记录</span>`;
 $('download-json').href=`/api/research/${record.id}/json`;$('download-md').href=`/api/research/${record.id}/markdown`;$('download-md').hidden=record.status!=='completed';
 if(record.report){const r=record.report;$('report').innerHTML=`<div class="summary"><strong>研究摘要 ${record.mode==='demo'?'· 教学演示':''}</strong>${esc(r.summary)}</div>`+r.sections.map(s=>`<h3>${esc(s.heading)}</h3>${s.claims.map(claim).join('')}`).join('')+`<h3>关键结论</h3>${r.key_conclusions.map(claim).join('')}<h3>遗留问题</h3><ul class="questions">${r.open_questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul>`;
 }else if(record.error){$('report').innerHTML=`<div class="failure">${esc(record.error)}</div>`;}else{$('report').innerHTML=`<div class="loading">◌ 正在${esc(kinds[record.process.at(-1)?.kind]||'准备研究')}…<br>打开“研究过程”可以查看已保存的步骤。</div>`;}
 $('sources').innerHTML=record.sources.length?record.sources.map(s=>`<div class="source" id="source-${s.id}"><a class="source-title" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">[${s.id}] ${esc(s.title)} ↗</a><span class="source-url">${esc(s.url)}</span><p>${esc(s.snippet)}</p><div class="source-meta">${esc(s.site)} · ${esc(s.date)} · ${esc(s.reading_method)}<br>访问时间 ${esc(s.accessed_at)}</div></div>`).join(''):'<p class="hint">等待检索结果。</p>';
 $('process').innerHTML=record.process.map(s=>`<div class="step"><div class="step-head">${esc(kinds[s.kind]||s.kind)} <small>第 ${s.round} 轮 · ${esc(s.time)}</small></div><p>${esc(s.detail)}</p></div>`).join('');
 const c=record.confidence;$('confidence').innerHTML=c?`<b>${esc(c.level)}</b><p>关键结论引用覆盖：${esc(c.citation_coverage)}</p><p>${esc(c.explanation)}</p><p>资料访问截止<br>${esc(c.cutoff)}</p>${c.limitations.map(x=>`<p>· ${esc(x)}</p>`).join('')}`:'研究完成后显示置信度与资料时效说明。';
}
async function select(id){activeId=id;clearTimeout(timer);try{const record=await api('/api/research/'+id);if(id!==activeId)return;render(record);if(['pending','running'].includes(record.status))timer=setTimeout(()=>select(id),900);else history();}catch(e){if(id===activeId)showError(e);}}
async function startResearch(input){if(creating)throw Error('正在创建任务，请稍候');creating=true;$('start').disabled=true;$('error').hidden=true;try{const value=await api('/api/research',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(input)});await history();await select(value.research_id);return value;}finally{creating=false;$('start').disabled=false;}}
$('research-form').onsubmit=async e=>{e.preventDefault();try{await startResearch({topic:$('topic').value.trim(),mode:$('mode').value,max_rounds:Number($('rounds').value)});}catch(error){showError(error);}};
function tab(name){document.querySelectorAll('[data-tab]').forEach(b=>{const selected=b.dataset.tab===name;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;});['report','sources','process'].forEach(id=>$(id).hidden=id!==name);}
document.querySelectorAll('[data-tab]').forEach((b,i,buttons)=>{b.onclick=()=>tab(b.dataset.tab);b.onkeydown=e=>{if(['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();const n=(i+(e.key==='ArrowRight'?1:-1)+buttons.length)%buttons.length;tab(buttons[n].dataset.tab);buttons[n].focus();}};});
$('report').onclick=e=>{const a=e.target.closest('[data-source]');if(a){e.preventDefault();tab('sources');$('source-'+a.dataset.source)?.scrollIntoView({behavior:'smooth',block:'center'});}};
if(document.modelContext?.registerTool){try{Promise.resolve(document.modelContext.registerTool({name:'start_research',description:'Create a local research task and display its current result. Demo uses the fixed RAG topic; live uses configured external APIs.',inputSchema:{type:'object',properties:{topic:{type:'string',minLength:2,maxLength:200},mode:{type:'string',enum:['demo','live']},max_rounds:{type:'integer',minimum:2,maximum:4}},required:['topic','mode','max_rounds'],additionalProperties:false},annotations:{readOnlyHint:false},execute:async input=>{if(!input||typeof input.topic!=='string'||!['demo','live'].includes(input.mode)||!Number.isInteger(input.max_rounds))throw Error('Invalid input');return startResearch(input);}})).catch(()=>{});}catch{}}
history();tab('report');
